import { useEffect, useRef, useState, type ReactNode } from "react";
import { cn } from "@registry/aikoz/lib/utils";
import { Dialog } from "@registry/aikoz/dialog/dialog";
import { Button } from "@registry/aikoz/button/button";
import { Input } from "@registry/aikoz/input/input";
import { SlotPicker, type SlotDay } from "@registry/aikoz/slot-picker/slot-picker";

// ─── Types ────────────────────────────────────────────────────────────────────

export interface BookingValues {
  name: string;
  email: string;
  company?: string;
  slot: string;
}

export type BookingStatus = "form" | "sending" | "confirmed" | "failed";

export interface BookingFlowProps {
  trigger?: ReactNode;
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
  title?: string;
  description?: string;
  days: SlotDay[];
  /**
   * État affiché. Contrôlé par l'appelant : c'est LUI qui parle au serveur,
   * ce composant ne fait que rendre l'état qu'on lui donne.
   */
  status?: BookingStatus;
  onSubmit?: (values: BookingValues) => void;
  /** Message d'échec. Il doit dire quoi faire, pas seulement que ça a raté. */
  failureMessage?: string;
  className?: string;
}

// ─── Composant ────────────────────────────────────────────────────────────────

/**
 * Prise de rendez-vous — la modale du tunnel du prototype site.
 *
 * **Ce composant ne parle à personne.** Il ne connaît ni serveur ni
 * `fetch` : l'appelant lui passe un `status` et reçoit un `onSubmit`. Un
 * composant de design system qui déclencherait lui-même un appel réseau
 * serait intestable et impossible à réutiliser — et il imposerait sa forme
 * d'API à toutes les applications qui l'installent.
 *
 * **Les deux états de confirmation ne remplacent pas la modale, ils la
 * remplissent.** Le titre reste le même repère, le contenu change. C'est ce
 * qui permet au focus de rester dans un dialogue déjà nommé plutôt que de
 * repartir de zéro.
 *
 * **Le changement d'état est annoncé ET reçoit le focus.** Deux mécanismes,
 * parce qu'ils ne servent pas la même personne : `role="status"` prévient
 * qui écoute, le focus déplacé emmène qui navigue au clavier là où se trouve
 * la suite. Sans le focus, l'utilisateur resterait sur un bouton
 * « Confirmer » qui n'existe plus, et repartirait du début du document.
 *
 * La validation se fait à la SOUMISSION, jamais à la frappe : corriger
 * quelqu'un pendant qu'il écrit affiche une erreur dès le premier caractère.
 */
export function BookingFlow({
  trigger,
  open,
  onOpenChange,
  title = "Réserver une démonstration",
  description = "Trente minutes, en visioconférence, avec un consultant.",
  days,
  status = "form",
  onSubmit,
  failureMessage = "L'envoi n'a pas abouti. Vérifiez votre connexion et réessayez ; si le problème persiste, écrivez à contact@okuden.fr.",
  className,
}: BookingFlowProps) {
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [company, setCompany] = useState("");
  const [slot, setSlot] = useState("");
  const [errors, setErrors] = useState<Partial<Record<keyof BookingValues, string>>>({});
  const finRef = useRef<HTMLParagraphElement>(null);
  // Le premier champ en erreur, pour y emmener le focus après une soumission
  // refusée. Sans lui l'utilisateur reste sur « Confirmer », trois `role=
  // "alert"` partent en même temps — les lecteurs d'écran en font la queue ou
  // en perdent — et il ne lui reste qu'à remonter le formulaire à tâtons.
  const nomRef = useRef<HTMLInputElement>(null);
  const emailRef = useRef<HTMLInputElement>(null);
  const creneauRef = useRef<HTMLFieldSetElement>(null);

  // Le focus suit l'état. À l'arrivée d'une confirmation ou d'un échec, il
  // se pose sur le message : sans ça il resterait sur un bouton disparu.
  useEffect(() => {
    if (status === "confirmed" || status === "failed") finRef.current?.focus();
  }, [status]);

  /**
   * Valide, et rend le premier champ fautif — `null` si tout va bien.
   *
   * Rendre le champ plutôt qu'un booléen est ce qui permet d'y emmener le
   * focus. « Le formulaire est invalide » ne dit pas OÙ, et c'est justement
   * ce que l'utilisateur a besoin de savoir.
   */
  function valider(): "name" | "email" | "slot" | null {
    const e: typeof errors = {};
    if (!name.trim()) e.name = "Indiquez votre nom, pour savoir qui nous rencontrons.";
    // Volontairement permissif : une adresse valide au sens de la norme peut
    // ne pas ressembler à ce qu'on imagine. On refuse l'absence d'arobase ou
    // de domaine, pas les formes inhabituelles.
    if (!email.includes("@") || !email.split("@")[1]?.includes("."))
      e.email = "L'adresse doit contenir un domaine, par exemple prenom.nom@exemple.fr.";
    if (!slot) e.slot = "Choisissez un créneau pour poursuivre.";
    setErrors(e);
    // L'ordre est celui du formulaire : on emmène au PREMIER problème, pas au
    // premier trouvé par l'objet.
    return (["name", "email", "slot"] as const).find((k) => e[k]) ?? null;
  }

  const enCours = status === "sending";

  return (
    <Dialog
      trigger={trigger}
      open={open}
      onOpenChange={onOpenChange}
      title={title}
      description={status === "form" ? description : undefined}
      className={className}
      footer={
        status === "form" ? (
          <Button
            onClick={() => {
              const fautif = valider();
              if (fautif) {
                // Le focus va au champ, pas au message : c'est là qu'on
                // corrige, et le message le suit par `aria-describedby`.
                if (fautif === "slot") {
                  // Un `<fieldset>` ne prend pas le focus. On vise le premier
                  // créneau SÉLECTIONNABLE : emmener sur un créneau complet
                  // serait emmener dans une impasse.
                  creneauRef.current
                    ?.querySelector<HTMLInputElement>(
                      'input[type="radio"]:not([disabled])',
                    )
                    ?.focus();
                } else {
                  (fautif === "name" ? nomRef : emailRef).current?.focus();
                }
                return;
              }
              onSubmit?.({ name, email, company: company || undefined, slot });
            }}
            disabled={enCours}
          >
            {enCours ? "Envoi…" : "Confirmer le rendez-vous"}
          </Button>
        ) : undefined
      }
    >
      {status === "form" && (
        <div className="flex flex-col gap-5">
          <div className="grid gap-4 sm:grid-cols-2">
            <Input
              ref={nomRef}
              label="Nom"
              required
              autoComplete="name"
              value={name}
              onChange={(e) => setName(e.target.value)}
              error={errors.name}
            />
            <Input
              ref={emailRef}
              label="Adresse e-mail"
              type="email"
              required
              autoComplete="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              error={errors.email}
            />
          </div>
          <Input
            label="Établissement"
            optional
            autoComplete="organization"
            description="Cela nous permet de préparer des exemples de votre réseau."
            value={company}
            onChange={(e) => setCompany(e.target.value)}
          />
          <SlotPicker
            ref={creneauRef}
            legend="Choisissez un créneau"
            days={days}
            value={slot}
            onValueChange={setSlot}
            error={errors.slot}
          />
        </div>
      )}

      {(status === "confirmed" || status === "failed") && (
        <div className="flex flex-col items-center gap-3 py-4 text-center">
          <span
            aria-hidden="true"
            className={cn(
              "inline-flex size-12 items-center justify-center rounded-full",
              status === "confirmed"
                ? "bg-[var(--success-subtle)] text-[var(--success)]"
                : "bg-[var(--error-subtle)] text-[var(--destructive-text)]"
            )}
          >
            <svg aria-hidden="true" viewBox="0 0 24 24" className="size-6" fill="none" stroke="currentColor" strokeWidth="2.25" strokeLinecap="round" strokeLinejoin="round">
              {status === "confirmed" ? <path d="M4 12.5 9.5 18 20 6.5" /> : <path d="M12 7v6M12 17h.01" />}
            </svg>
          </span>
          {/* `tabIndex={-1}` : focalisable par script, jamais par tabulation.
              Le `role="status"` annonce, le focus emmène — deux canaux pour
              deux façons de naviguer. */}
          <p
            ref={finRef}
            tabIndex={-1}
            role="status"
            className="m-0 text-base font-semibold text-foreground focus-visible:outline-none"
          >
            {status === "confirmed"
              ? "C'est confirmé."
              : "Le rendez-vous n'a pas pu être enregistré."}
          </p>
          <p className="m-0 max-w-sm text-sm text-muted-foreground text-balance">
            {status === "confirmed"
              ? "Vous recevez une invitation par e-mail dans les prochaines minutes. Elle contient le lien de connexion."
              : failureMessage}
          </p>
        </div>
      )}
    </Dialog>
  );
}

import { useId, forwardRef} from "react";
import { cn } from "@registry/aikoz/lib/utils";

// ─── Types ────────────────────────────────────────────────────────────────────

export interface Slot {
  /** Identifiant du créneau — un ISO 8601 complet, en général. */
  value: string;
  /** Heure affichée : « 09:30 ». */
  time: string;
  /** Créneau déjà pris. Reste annoncé, mais non sélectionnable. */
  full?: boolean;
}

export interface SlotDay {
  /** Jour en clair : « Mardi 14 avril ». C'est lui qui nomme la liste. */
  label: string;
  slots: Slot[];
}

export interface SlotPickerProps {
  /** Question posée — **obligatoire**, rendue en `<legend>`. */
  legend: string;
  days: SlotDay[];
  value?: string;
  onValueChange?: (value: string) => void;
  /** Message d'erreur, annoncé en `role="alert"`. */
  error?: string;
  /** Texte affiché quand aucun jour n'a de créneau. */
  emptyLabel?: string;
  className?: string;
}

// ─── Composant ────────────────────────────────────────────────────────────────

/**
 * Choix d'un créneau.
 *
 * **Un seul `<fieldset>` pour tous les jours, pas un par jour.** Le choix est
 * unique sur l'ensemble : imbriquer un groupe de radios par journée
 * laisserait croire qu'on choisit une heure dans chaque, et casserait le
 * parcours aux flèches — qui, avec un `name` commun, traverse nativement
 * toute la grille, d'un jour à l'autre. Les jours nomment leur liste par
 * `aria-labelledby`, ce qui donne le contexte sans découper le groupe.
 *
 * **Un créneau complet reste annoncé.** Il est `disabled`, donc sauté par les
 * flèches, mais il est toujours lu — « 11:00, complet ». Le retirer de la
 * grille ferait disparaître l'information : l'utilisateur ne saurait pas que
 * ce créneau existe et qu'il est pris, il croirait que le cabinet n'ouvre
 * pas à cette heure-là.
 *
 * **L'état complet ne tient pas à la couleur** : texte barré, opacité,
 * `disabled` annoncé, et la mention « complet » en `sr-only`.
 */
export const SlotPicker = forwardRef<HTMLFieldSetElement, SlotPickerProps>(
  function SlotPicker({
  legend,
  days,
  value,
  onValueChange,
  error,
  emptyLabel = "Aucun créneau disponible sur cette période.",
  className,
}, ref) {
  const uid = useId();
  const errId = error ? `${uid}-err` : undefined;
  const vide = days.every((d) => d.slots.length === 0);

  return (
    <fieldset
      // La référence sert à emmener le focus ici après une soumission
      // refusée : `BookingFlow` y cherche le premier créneau sélectionnable.
      // Un `<fieldset>` ne prend pas le focus lui-même, et lui en donner un
      // artificiellement ferait annoncer le groupe sans dire quoi faire.
      ref={ref}
      className={cn("m-0 p-0 border-0 flex flex-col gap-4", className)}
      aria-describedby={errId}
    >
      <legend className="p-0 text-sm font-medium text-foreground">{legend}</legend>

      {vide ? (
        <p className="m-0 text-sm text-muted-foreground">{emptyLabel}</p>
      ) : (
        days.map((day, i) => (
          <div key={day.label} className="flex flex-col gap-2">
            <span
              id={`${uid}-j${i}`}
              className="text-xs font-semibold uppercase tracking-wider text-muted-foreground"
            >
              {day.label}
            </span>
            <div
              role="group"
              aria-labelledby={`${uid}-j${i}`}
              className="grid grid-cols-[repeat(auto-fill,minmax(5rem,1fr))] gap-2"
            >
              {day.slots.map((s) => (
                <label
                  key={s.value}
                  className={cn(
                    "relative inline-flex items-center justify-center",
                    // 44px : un créneau se vise au pouce, souvent en marchant.
                    "min-h-11 rounded-[var(--radius)] border-2 text-sm tabular-nums",
                    "transition-colors cursor-pointer",
                    "has-[:focus-visible]:outline-none has-[:focus-visible]:ring-2",
                    "has-[:focus-visible]:ring-[var(--ring)] has-[:focus-visible]:ring-offset-2",
                    "has-[:focus-visible]:ring-offset-[var(--background)]",
                    s.full
                      ? "border-border bg-[var(--muted)] text-muted-foreground line-through cursor-not-allowed opacity-70"
                      : cn(
                          "border-[var(--border-strong)] bg-[var(--card)] text-foreground",
                          "hover:bg-[var(--surface-hover)]",
                          // Comme dans `ChoiceCard` : le trait retenu et le
                          // trait au repos ne se séparent que de 1,30:1 en
                          // clair. C'est donc l'INVERSION du fond qui porte
                          // l'état, pas la teinte du trait.
                          "has-[:checked]:border-[var(--primary)]",
                          "has-[:checked]:bg-[var(--primary)]",
                          "has-[:checked]:text-[var(--primary-foreground)]",
                          "has-[:checked]:font-semibold"
                        )
                  )}
                >
                  <input
                    type="radio"
                    // Un `name` commun à TOUS les jours : c'est ce qui fait du
                    // tout un seul groupe, et ce qui laisse les flèches
                    // traverser la grille entière.
                    name={`${uid}-creneau`}
                    value={s.value}
                    checked={value === s.value}
                    disabled={s.full}
                    onChange={() => onValueChange?.(s.value)}
                    // Nom composé en UNE chaîne. Un `sr-only` séparé portant
                    // « , complet » donnait « 11:00 , complet » : l'algorithme
                    // de nom accessible joint les éléments par une espace, et
                    // la virgule se détachait. Le nom contient toujours
                    // l'heure visible, ce qu'exige WCAG 2.5.3.
                    aria-label={s.full ? `${s.time}, complet` : undefined}
                    className="sr-only"
                  />
                  {s.time}
                </label>
              ))}
            </div>
          </div>
        ))
      )}

      {error && (
        <p id={errId} role="alert" className="m-0 text-xs text-[var(--destructive-text)]">
          {error}
        </p>
      )}
    </fieldset>
  );
});

import { type ReactNode } from "react";
import * as DialogPrimitive from "@radix-ui/react-dialog";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@registry/aikoz/lib/utils";

// ─── Variants ────────────────────────────────────────────────────────────────

const contentVariants = cva(
  [
    "fixed z-50 flex flex-col gap-4 bg-card text-card-foreground",
    "border border-border shadow-lg",
    "focus:outline-none",
    // Une modale plus haute que l'écran doit défiler d'elle-même, sinon son
    // bouton de validation devient inatteignable en zoom 200 % (WCAG 1.4.10).
    "max-h-[calc(100dvh-2rem)] overflow-y-auto",
  ],
  {
    variants: {
      placement: {
        /** Modale centrée — confirmation, formulaire court. */
        center: [
          "left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2",
          "w-[calc(100vw-2rem)] max-w-lg rounded-[var(--radius)]",
        ],
        /** Panneau latéral — filtres, détail d'une ligne. */
        right: [
          "right-0 top-0 h-dvh max-h-dvh w-[calc(100vw-3rem)] max-w-md",
          "rounded-l-[var(--radius)]",
        ],
        /** Feuille basse — le réflexe mobile. */
        bottom: [
          "bottom-0 left-0 right-0 max-h-[85dvh]",
          "rounded-t-[var(--radius)]",
        ],
      },
      density: { compact: "p-4", default: "p-6" },
    },
    defaultVariants: { placement: "center", density: "default" },
  }
);

// ─── Types ────────────────────────────────────────────────────────────────────

export interface DialogProps extends VariantProps<typeof contentVariants> {
  /** Élément déclencheur. Le focus lui revient automatiquement à la fermeture. */
  trigger?: ReactNode;
  /**
   * Titre — **obligatoire**. Il nomme la modale pour les lecteurs d'écran.
   * Une modale sans nom s'annonce « dialogue », sans dire lequel.
   */
  title: string;
  /**
   * Titre visuellement masqué. Pour une modale dont le contenu porte déjà son
   * propre en-tête ; le nom accessible reste nécessaire.
   */
  titleHidden?: boolean;
  /** Texte d'introduction, associé par `aria-describedby`. */
  description?: string;
  children: ReactNode;
  /** Barre d'actions, rendue en bas. */
  footer?: ReactNode;
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
  /** Libellé du bouton de fermeture. */
  closeLabel?: string;
  className?: string;
}

// ─── Composant ────────────────────────────────────────────────────────────────

/**
 * Modale et panneau latéral — un seul composant, trois placements.
 *
 * Bâti sur Radix, qui fournit ce qu'on rate presque toujours à la main : le
 * piège de focus, le retour du focus au déclencheur à la fermeture, la touche
 * Échap, le verrouillage du défilement de la page, et le masquage du reste du
 * document.
 *
 * **Le masquage passe par `aria-hidden` sur les frères, pas par
 * `aria-modal`.** Ce commentaire annonçait l'attribut ; vérifié au rendu, il
 * n'y est pas — Radix ne le pose plus. Ce n'est pas un manque : `aria-modal`
 * a une histoire de bogues dans les lecteurs d'écran, et masquer réellement
 * le reste du document est la technique plus sûre, celle que l'APG privilégie
 * désormais. Mesuré à l'ouverture : tous les frères du conteneur de la modale
 * portent `aria-hidden="true"`, et la modale n'est elle-même dans aucun
 * conteneur masqué.
 *
 * Le titre est un prop obligatoire, pas un enfant libre : c'est la seule façon
 * de garantir que la modale a un nom accessible.
 *
 * **Pas d'animation d'ouverture.** Il y en avait une, écrite en classes
 * `animate-in` / `animate-out` — sauf que ces classes viennent du plugin
 * `tailwindcss-animate`, qui n'est pas installé. Elles ne produisaient donc
 * RIEN : `animationName` valait `none`, vérifié à l'exécution. Une classe
 * morte est pire qu'une absence, elle laisse croire que le comportement
 * existe. Si une animation devient souhaitable, ce sera une décision
 * explicite, avec la dépendance qui va avec.
 */
export function Dialog({
  trigger,
  title,
  titleHidden = false,
  description,
  children,
  footer,
  placement,
  density,
  open,
  onOpenChange,
  closeLabel = "Fermer",
  className,
}: DialogProps) {
  return (
    <DialogPrimitive.Root open={open} onOpenChange={onOpenChange}>
      {trigger && <DialogPrimitive.Trigger asChild>{trigger}</DialogPrimitive.Trigger>}
      <DialogPrimitive.Portal>
        <DialogPrimitive.Overlay
          className={cn(
            "fixed inset-0 z-40 bg-[color-mix(in_oklch,var(--foreground),transparent_45%)]"
          )}
        />
        <DialogPrimitive.Content
          className={cn(contentVariants({ placement, density }), className)}
        >
          <div className="flex items-start justify-between gap-4">
            <div className="flex flex-col gap-1 min-w-0">
              <DialogPrimitive.Title
                className={cn(
                  "font-heading text-lg font-bold text-foreground m-0",
                  titleHidden && "sr-only"
                )}
              >
                {title}
              </DialogPrimitive.Title>
              {description && (
                <DialogPrimitive.Description className="text-sm text-muted-foreground m-0">
                  {description}
                </DialogPrimitive.Description>
              )}
            </div>
            <DialogPrimitive.Close
              className={cn(
                "shrink-0 rounded-[var(--radius)] p-1 text-muted-foreground",
                "hover:text-foreground hover:bg-[var(--surface-hover)]",
                "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--ring)]",
                // 24px de cible visible, portée à 44px par la zone tactile —
                // WCAG 2.5.8 demande 24px au minimum, les doigts en demandent plus.
                "relative after:absolute after:inset-[-10px] after:content-['']"
              )}
              aria-label={closeLabel}
            >
              <span aria-hidden="true" className="block size-6 leading-6 text-center">
                ×
              </span>
            </DialogPrimitive.Close>
          </div>

          <div className="flex-1">{children}</div>

          {footer && <div className="flex gap-3 flex-wrap justify-end">{footer}</div>}
        </DialogPrimitive.Content>
      </DialogPrimitive.Portal>
    </DialogPrimitive.Root>
  );
}

export { contentVariants as dialogVariants, DialogPrimitive };

import { forwardRef, useId, type InputHTMLAttributes, type ReactNode } from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@registry/aikoz/lib/utils";

// ─── Variants ────────────────────────────────────────────────────────────────

const fieldVariants = cva(
  [
    "w-full rounded-[var(--radius)] bg-[var(--card)] text-foreground",
    "border border-[var(--input)]",
    "placeholder:text-[var(--muted-foreground)]",
    "transition-colors",
    "focus-visible:outline-none focus-visible:border-[var(--ring)]",
    "focus-visible:ring-2 focus-visible:ring-[var(--ring)] focus-visible:ring-offset-1",
    "focus-visible:ring-offset-[var(--background)]",
    // `disabled` retire du parcours clavier ET de la soumission. Quand la
    // valeur doit rester lisible et envoyée, c'est `readOnly` qu'il faut —
    // il garde le champ focusable, donc découvrable.
    "disabled:cursor-not-allowed disabled:opacity-60",
    // L'état lecture seule est porté par un TRAIT TIRETÉ, pas par le fond :
    // --muted ne se détache pas de --card (1,00 à 1,19:1 selon la combinaison
    // registre × thème, strictement identique en produit sombre). Un état
    // signalé par un fond invisible n'est pas signalé du tout. Le tireté tient
    // sans dépendre d'un contraste, et le lecteur d'écran annonce readonly
    // nativement.
    "read-only:border-dashed read-only:bg-[var(--muted)] read-only:cursor-default",
  ],
  {
    variants: {
      size: {
        sm: "min-h-9 px-3 py-2 text-sm",
        md: "min-h-11 px-3.5 py-2.5 text-sm",
        lg: "min-h-12 px-4 py-3 text-base",
      },
      invalid: {
        true: "border-[var(--destructive-text)] focus-visible:border-[var(--destructive-text)] focus-visible:ring-[var(--destructive-text)]",
        false: "",
      },
    },
    defaultVariants: { size: "md", invalid: false },
  }
);

// ─── Types ────────────────────────────────────────────────────────────────────

export interface InputProps
  extends Omit<InputHTMLAttributes<HTMLInputElement>, "size">,
    Pick<VariantProps<typeof fieldVariants>, "size"> {
  /**
   * Libellé visible et persistant. **Obligatoire** : un `placeholder` n'est pas
   * un libellé — il disparaît à la saisie, laissant l'utilisateur sans repère
   * sur ce qu'il est en train de remplir.
   */
  label: string;
  /**
   * Rend le libellé en `sr-only`. Réservé au champ de recherche, où la loupe et
   * le placeholder portent l'affordance visuelle. Partout ailleurs, un libellé
   * invisible prive les voyants d'un repère que les autres ont.
   */
  labelHidden?: boolean;
  /**
   * Consigne affichée AVANT le champ — format attendu, contrainte. Placée après,
   * elle arrive trop tard : l'utilisateur a déjà saisi.
   */
  description?: string;
  /**
   * Marque le champ **facultatif**, en toutes lettres à côté du libellé.
   *
   * *Practical UI* (chapitre 8) et les guides d'accessibilité demandent la
   * même chose : on marque les obligatoires OU les facultatifs, et on ne
   * laisse jamais l'utilisateur deviner lesquels sont lesquels. Un formulaire
   * où trois champs sur quatre portent une astérisque a choisi le mauvais
   * camp — c'est le quatrième qu'il fallait nommer.
   *
   * Le marqueur est **visible**, pas `sr-only` : celui qui voit l'écran a
   * exactement le même besoin de savoir qu'il peut passer son chemin.
   *
   * Sans effet si `required` est posé. Un champ marqué des deux façons ne
   * veut rien dire ; plutôt que d'échouer à la compilation — ce qui rendait
   * `args: { required: true }` inexprimable dans les histoires et compliquait
   * la vie de qui étale des props — l'obligation l'emporte, toujours, et
   * l'audit des formulaires vérifie qu'aucun champ ne porte les deux
   * marqueurs à l'écran.
   */
  optional?: boolean;
  /**
   * Message d'erreur. Doit nommer le problème ET dire comment le corriger :
   * « Le nom doit faire au moins 2 caractères », pas « Champ invalide ».
   * Sa présence bascule le champ en `aria-invalid`.
   */
  error?: string;
  /** Icône décorative en tête de champ — la loupe d'une recherche. */
  leadingIcon?: ReactNode;
  /** Élément de fin de champ : unité, bouton d'effacement. */
  trailingSlot?: ReactNode;
  className?: string;
  /** Classe du conteneur, pour la mise en page. */
  wrapperClassName?: string;
}


// ─── Composant ────────────────────────────────────────────────────────────────

/**
 * Champ de saisie — les 4 états du composant Figma : défaut, focus, erreur,
 * désactivé.
 *
 * Ne valide rien de lui-même : c'est l'appelant qui décide quand. La règle à
 * suivre est de valider **à la sortie du champ**, jamais à la frappe — corriger
 * quelqu'un pendant qu'il écrit produit une erreur affichée dès le premier
 * caractère.
 *
 * Rappel des attributs à passer selon l'usage, ils changent le clavier affiché
 * sur mobile et débloquent le remplissage automatique (WCAG 1.3.5) :
 *
 *   nom d'agence   type="text"   autoComplete="organization"
 *   recherche      type="search" autoComplete="off"
 *   e-mail         type="email"  autoComplete="email"
 *   téléphone      type="tel"    autoComplete="tel"  inputMode="tel"
 *   code postal    type="text"   autoComplete="postal-code" inputMode="numeric"
 */
export const Input = forwardRef<HTMLInputElement, InputProps>(function Input(
  {
    label,
    labelHidden = false,
    optional = false,
    description,
    error,
    leadingIcon,
    trailingSlot,
    size = "md",
    required,
    id,
    className,
    wrapperClassName,
    ...props
  },
  ref
) {
  const generated = useId();
  const fieldId = id ?? `input-${generated}`;
  const descId = `${fieldId}-desc`;
  const errId = `${fieldId}-err`;

  const describedBy =
    [description ? descId : null, error ? errId : null].filter(Boolean).join(" ") ||
    undefined;

  return (
    <div className={cn("flex flex-col gap-1.5", wrapperClassName)}>
      <label
        htmlFor={fieldId}
        className={cn(
          "text-sm font-medium text-foreground",
          labelHidden && "sr-only"
        )}
      >
        {label}
        {required && (
          <>
            {/* L'astérisque est décoratif ; l'obligation est dite en toutes
                lettres, jamais portée par le seul symbole. */}
            <span aria-hidden="true" className="text-[var(--destructive-text)]">
              {" "}
              *
            </span>
            <span className="sr-only"> (obligatoire)</span>
          </>
        )}
        {!required && optional && (
          // Visible, jamais `sr-only` : qui voit l'écran a le même
          // besoin de savoir qu'il peut passer son chemin.
          <span className="ml-1 font-regular text-muted-foreground">
            (facultatif)
          </span>
        )}
      </label>

      {/* La consigne précède le champ — elle sert à le remplir, pas à le relire. */}
      {description && (
        <p id={descId} className="text-xs text-muted-foreground m-0">
          {description}
        </p>
      )}

      <div className="relative flex items-center">
        {leadingIcon && (
          <span
            className="absolute left-3 flex items-center text-muted-foreground pointer-events-none"
            aria-hidden="true"
          >
            {leadingIcon}
          </span>
        )}
        <input
          ref={ref}
          id={fieldId}
          required={required}
          aria-required={required || undefined}
          aria-invalid={error ? true : undefined}
          aria-describedby={describedBy}
          className={cn(
            fieldVariants({ size, invalid: !!error }),
            leadingIcon && "pl-9",
            trailingSlot && "pr-10",
            className
          )}
          {...props}
        />
        {trailingSlot && (
          <span className="absolute right-3 flex items-center">{trailingSlot}</span>
        )}
      </div>

      {/* role="alert" : l'erreur apparaît après coup, elle doit être annoncée
          sans que l'utilisateur ait à retourner la chercher. */}
      {error && (
        <p
          id={errId}
          role="alert"
          className="text-xs text-[var(--destructive-text)] m-0"
        >
          {error}
        </p>
      )}
    </div>
  );
});

export { fieldVariants as inputVariants };

import { forwardRef, type ButtonHTMLAttributes } from "react";
import { Slot } from "@radix-ui/react-slot";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@registry/aikoz/lib/utils";

// ─── Variants ────────────────────────────────────────────────────────────────

const buttonVariants = cva(
  [
    "inline-flex items-center justify-center gap-2",
    "rounded-full font-medium",
    // Pas de `whitespace-nowrap` : avec lui, un libellé long sortait du
    // conteneur et se faisait rogner — un bouton qui découpe son propre
    // libellé est cassé, et sur mobile le texte disparaissait purement.
    // Le repli gracieux est le retour à la ligne : la pastille s'allonge,
    // ce qui signale au passage qu'il faut raccourcir l'intitulé.
    "max-w-full text-center text-balance",
    "transition-colors duration-150",
    "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--ring)]",
    "focus-visible:ring-offset-2 focus-visible:ring-offset-[var(--background)]",
    "disabled:pointer-events-none disabled:opacity-50 disabled:cursor-not-allowed",
  ],
  {
    variants: {
      variant: {
        default: [
          // Le liseré n'est PAS décoratif. En thème sombre, le fond de l'action
          // primaire est une couleur de marque vive, donc à peine plus claire
          // que la carte : le libellé se lit (APCA 84 à 90) mais la FORME du
          // bouton ne se détache pas du bloc — sous le seuil de 45 d'un
          // élément d'interface. Le liseré la rend identifiable sans toucher
          // au fond, donc sans rien céder sur la vivacité de la marque.
          //
          // En clair, `--primary-edge` vaut `--primary` : le liseré existe,
          // ne se voit pas, et ne coûte rien.
          "bg-[var(--primary)] text-[var(--primary-foreground)]",
          "border border-[var(--primary-edge)]",
          "hover:bg-[color-mix(in_oklch,var(--primary),transparent_10%)] active:bg-[color-mix(in_oklch,var(--primary),transparent_20%)]",
        ],
        secondary: [
          "bg-[var(--secondary)] text-[var(--secondary-foreground)]",
          "hover:bg-[color-mix(in_oklch,var(--secondary),transparent_10%)] active:bg-[color-mix(in_oklch,var(--secondary),transparent_20%)]",
        ],
        // Le survol de ces deux variantes est porté par la BORDURE, pas par une
        // teinte. Mesuré : un voile d'accent à 12 % donne 1,025:1 sur fond
        // clair — invisible. Monter l'opacité n'y change rien (1,073 à 40 %) :
        // l'aquamarine a presque la même luminance que le fond clair, on
        // déplace la teinte sans déplacer la clarté. La bordure forte, elle,
        // tient 4,07 à 4,58:1 selon le thème.
        outline: [
          "border border-[var(--border)] bg-transparent text-[var(--foreground)]",
          "hover:border-[var(--border-strong)] hover:bg-[var(--surface-hover)]",
          "active:bg-[var(--surface-active,var(--surface-hover))]",
        ],
        ghost: [
          // Bordure transparente au repos : elle apparaît au survol sans
          // décaler la mise en page d'un pixel.
          "border border-transparent bg-transparent text-[var(--foreground)]",
          "hover:border-[var(--border-strong)] hover:bg-[var(--surface-hover)]",
          "active:bg-[var(--surface-active,var(--surface-hover))]",
        ],
      },
      size: {
        // 36 px : la densité d'une barre d'outils, assumée à la souris.
        // Au doigt elle tombe sous le confort de 44 px (AAA 2.5.5, Apple HIG),
        // d'où `tactile:` — mesuré sur le tableau de bord, « Exporter » valait
        // 39 px de haut.
        sm: "min-h-9 tactile:min-h-11 px-4 py-2 text-sm",
        md: "min-h-11 px-6 py-2.5 text-sm",
        lg: "min-h-12 px-8 py-3 text-base",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "md",
    },
  }
);

// ─── Types ────────────────────────────────────────────────────────────────────

export interface ButtonProps
  extends ButtonHTMLAttributes<HTMLButtonElement>,
    VariantProps<typeof buttonVariants> {
  asChild?: boolean;
}

// ─── Component ────────────────────────────────────────────────────────────────

export const Button = forwardRef<HTMLButtonElement, ButtonProps>(
  ({ className, variant, size, asChild = false, type, ...props }, ref) => {
    const Comp = asChild ? Slot : "button";
    return (
      <Comp
        ref={ref}
        className={cn(buttonVariants({ variant, size }), className)}
        /* Sans type explicite, un <button> dans un <form> vaut type="submit"
           et soumet le formulaire au moindre clic. Le défaut sûr est "button" ;
           un bouton de soumission le déclare. Ne s'applique pas à asChild, où
           l'élément rendu n'est pas forcément un bouton. */
        {...(asChild ? {} : { type: type ?? "button" })}
        {...props}
      />
    );
  }
);
Button.displayName = "Button";

export { buttonVariants };

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}
